import React from 'react';import './Dashboard.css';
const metrics=[['Total Leads','1,284','+12.8%','◉','blue'],['Site Visits','86','+8.2%','⌖','purple'],['Bookings','32','+18.4%','▣','green'],['Sales Revenue','₹4.82 Cr','+6.7%','₹','orange']];
export default function Dashboard({onNavigate}){return <div className="page"><div className="page-heading"><div><small>REAL ESTATE CRM · OVERVIEW</small><h1>Good morning, Manish 👋</h1><p>Here’s what’s happening across your real estate business today.</p></div><button className="primary" onClick={()=>onNavigate('Leads')}>＋ Add new lead</button></div><div className="metrics">{metrics.map(([l,v,c,i,t])=><div className="metric" key={l}><div className="metric-label">{l}<span className={'metric-icon '+t}>{i}</span></div><strong>{v}</strong><div className="metric-foot"><b>{c}</b> vs. last month</div></div>)}</div><div className="dash-grid"><section className="panel"><div className="panel-head"><div><h3>Sales performance</h3><p>Revenue overview · Last 6 months</p></div><span className="select-pill">This year⌄</span></div><div className="chart"><div className="chart-labels"><span>₹5 Cr</span><span>₹4 Cr</span><span>₹3 Cr</span><span>₹2 Cr</span><span>₹1 Cr</span></div><div className="chart-main"><div className="gridlines"><i/><i/><i/><i/><i/></div><svg viewBox="0 0 600 200" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#5573eb" stopOpacity=".22"/><stop offset="100%" stopColor="#5573eb" stopOpacity="0"/></linearGradient></defs><path d="M0 165 C45 150 65 140 100 143 S165 95 200 115 S270 80 300 93 S370 50 400 68 S470 28 500 43 S560 15 600 24 L600 200 L0 200Z" fill="url(#fill)"/><path d="M0 165 C45 150 65 140 100 143 S165 95 200 115 S270 80 300 93 S370 50 400 68 S470 28 500 43 S560 15 600 24" fill="none" stroke="#5573eb" strokeWidth="3" strokeLinecap="round"/></svg><div className="months"><span>Jan</span><span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span></div></div></div></section><section className="panel sources"><div className="panel-head"><div><h3>Lead sources</h3><p>Where your leads come from</p></div><span>•••</span></div><div className="donut-wrap"><div className="donut"><div><strong>1,284</strong><small>Total leads</small></div></div></div><div className="source-list"><div><i className="dblue"/>Property portals <b>42%</b></div><div><i className="dpurple"/>Social media <b>28%</b></div><div><i className="dgreen"/>Referral <b>18%</b></div><div><i className="dorange"/>Walk-in / Other <b>12%</b></div></div></section></div><div className="dash-grid bottom-grid"><section className="panel"><div className="panel-head"><div><h3>Recent leads</h3><p>Latest opportunities added to your pipeline</p></div><button className="link-btn" onClick={()=>onNavigate('Leads')}>View all →</button></div><div className="table-wrap"><table><thead><tr><th>LEAD</th><th>INTERESTED IN</th><th>STATUS</th><th>ASSIGNED TO</th></tr></thead><tbody><tr><td><b>Aditya Sharma</b><small>aditya.sharma@email.com</small></td><td>3 BHK · Noida</td><td><span className="pill blue-pill">Qualified</span></td><td>Rohit Verma</td></tr><tr><td><b>Priya Kapoor</b><small>+91 98765 43210</small></td><td>Residential Plot</td><td><span className="pill amber-pill">Follow-up</span></td><td>Neha Singh</td></tr><tr><td><b>Rahul Verma</b><small>rahul.v@email.com</small></td><td>Commercial Space</td><td><span className="pill green-pill">Site visit</span></td><td>Amit Kumar</td></tr></tbody></table></div></section><section className="panel agenda"><div className="panel-head"><div><h3>Today’s agenda</h3><p>Priority tasks and reminders</p></div><span className="agenda-num">3</span></div><div className="agenda-row"><time>10:30</time><i className="line-blue"/><div><b>Call Aditya Sharma</b><small>Discuss 3 BHK options · Noida</small><span>Lead follow-up</span></div></div><div className="agenda-row"><time>12:00</time><i className="line-purple"/><div><b>Site visit · Green Valley</b><small>Customer: Priya Kapoor</small><span className="purple-tag">Site visit</span></div></div><div className="agenda-row"><time>15:30</time><i className="line-green"/><div><b>Review booking documents</b><small>Unit A-1204 · Skyline Heights</small><span className="green-tag">Documentation</span></div></div></section></div><div className="demo-note">ⓘ <div><b>Preview mode</b><p>Sample figures are for layout preview only. Database, user access and notifications will be connected in a later step.</p></div></div></div>}
